          >
          <p class="error-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address</label>
          <input
            type="email"
            id="email"
            name="email"
            autocomplete="email"
            placeholder="alex@example.com"
            aria-describedby="email-error"
            aria-invalid="false"
            required
          >
          <p class="error-message" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
          <input
            type="tel"
            id="phone"
            name="phone"
            autocomplete="tel"
            placeholder="+1 555 123 4567"
            aria-describedby="phone-help phone-error"
            aria-invalid="false"
          >
          <p class="helper-text" id="phone-help">Expected format: include 7 to 15 digits, with optional spaces, dashes, parentheses, or a leading +.</p>
          <p class="error-message" id="phone-error" aria-live="polite"></p>
        </div>

        <button type="submit">Submit request</button>
      </form>

      <p class="success-message" id="success-message" role="status">Thanks! Your support request is ready to send.</p>
    </section>
  </main>

  <script>
    const form = document.querySelector("#contact-form");
    const successMessage = document.querySelector("#success-message");
    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        validate(value) {
          return value.trim() ? "" : "Full name is required.";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        validate(value) {
          const trimmed = value.trim();
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (!trimmed) {
            return "Email address is required.";
          }

          return emailPattern.test(trimmed) ? "" : "Enter a valid email address.";
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        validate(value) {
          const trimmed = value.trim();
          const allowedCharacters = /^\+?[0-9\s().-]+$/;
          const digitCount = trimmed.replace(/\D/g, "").length;

          if (!trimmed) {
            return "";
          }

          if (!allowedCharacters.test(trimmed)) {
            return "Use only numbers, spaces, dashes, parentheses, or a leading +.";
          }

          return digitCount >= 7 && digitCount <= 15
            ? ""
            : "Enter a phone number with 7 to 15 digits.";
        }
      }
    };

    function setFieldState(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldState(field, message);
      return !message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("input", () => {
        validateField(field);
        successMessage.classList.remove("is-visible");
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isValid = Object.values(fields).every(validateField);
      successMessage.classList.toggle("is-visible", isValid);

      if (isValid) {
        form.reset();
        Object.values(fields).forEach((field) => setFieldState(field, ""));
      }
    });
  </script>
